const LANGUAGE_ORDER = ["es", "pt", "zh", "ar", "ru", "ja"] as const;
export const localeExtraFill: Record<(typeof LANGUAGE_ORDER)[number], Record<string, string>> = { es: {}, pt: {}, zh: {}, ar: {}, ru: {}, ja: {} };
LANGUAGE_ORDER.forEach((language, index) => {
  const target = localeExtraFill[language];
  for (const row of [...rows, ...rows2]) target[row[0]] = row[index + 1];
  for (const [kind, en, ...texts] of styleRows) target[`${kind} · ${en}`] = `${stylePrefix[kind][index]} · ${texts[index]}`;
  for (const site of siteWords) for (const suffix of siteSuffix) target[`${site[0]} · ${suffix[0]}`] = `${site[index + 1]} · ${suffix[index + 1]}`;
});
